{
  "items": [
    {
      "title": "Hessian Statistical Information System (HESIS) – Historical Employment and Labor Market Statistics",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/datenbank-hesis",
      "justification": "Official statistical database maintained by the Hessian Statistical Office. Contains regional statistics on employment, economic activity, and labor market developments. Some datasets extend back to the 1970s, making this a valuable source for examining employment structures and working conditions in Hesse during the 1980s. Data can be filtered geographically and exported to Excel. Historical coverage varies by indicator."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2014",
      "url_or_doi": "https://search.gesis.org/research_data/ZA4584",
      "justification": "Longitudinal survey dataset covering German society from 1980 onward, including surveys conducted in 1980, 1982, 1984, 1986, and 1988. Contains information on employment, occupational status, socioeconomic circumstances, and attitudes toward work. The extended version includes federal-state identifiers, enabling the selection of respondents from Hesse. Particularly useful for investigating workers' experiences and occupational characteristics during the 1980s."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–1986",
      "url_or_doi": "https://data.gesis.org/datasearchkg/Dataset/10.4232/1.1335",
      "justification": "Harmonized survey dataset combining the 1980, 1982, 1984, and 1986 ALLBUS surveys. Provides individual-level information about employment, occupations, social characteristics, and attitudes. Useful for studying changes in workforce composition and employment experiences during the first half of the 1980s. Geographic identifiers for isolating Hesse may require access to the restricted extended data."
    },
    {
      "title": "ALLBUS – Individual Surveys and Extended Regional Datasets, 1980–1988",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "Official GESIS repository providing access to individual ALLBUS surveys from 1980, 1982, 1984, 1986, and 1988. The surveys contain demographic, occupational, and socioeconomic variables relevant to employment research. Extended datasets include federal-state identifiers, allowing researchers to focus specifically on Hesse. Access to extended regional data requires a user agreement. Particularly appropriate for comparing employment characteristics across the decade."
    },
    {
      "title": "Hessian Statistical Office – Historical Public-Sector Employment Statistics, 1950–2025",
      "url_or_doi": "https://statistik.hessen.de/presse/historischer-hoechststand-138755-vollzeitbeschaeftigte-des-landes-hessen-im-jahr-1981",
      "justification": "Official historical employment statistics documenting full-time and part-time employment in Hesse's state administration. Includes historical figures covering the 1980s, with full-time public-sector employment reaching 138,755 in 1981. Relevant for analyzing public-sector employment structures, working-time arrangements, and changes in the balance between full-time and part-time positions. Does not directly measure workplace safety or employee satisfaction."
    },
    {
      "title": "Historical Statistics (histat) – Population, Economy, Employment, Working Hours, and Wages in Germany, 1950–2010",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/de/project/details/291DF3124A0BDC5C85010D0D12BF9B05",
      "justification": "Historical statistical compilation containing time series on employment, working hours, wages, productivity, and economic conditions. Includes indicators such as average weekly working hours, contractual working time, annual leave, and full-time versus part-time employment. Covers the entire 1980s and provides national historical context for working conditions in Hesse. Researchers should verify which indicators offer state-level geographic breakdowns."
    },
    {
      "title": "Historical Statistics (histat) – German Economic and Social History Database",
      "url_or_doi": "https://histat.safe-frankfurt.de/",
      "justification": "Research database specializing in historical economic and social statistics. Provides historical datasets covering labor markets, wages, employment, industrial development, and working hours. Useful for identifying additional regional or sector-specific statistical series relevant to working conditions in Hesse during the 1980s. Dataset availability and geographic coverage vary, and registration may be required."
    },
    {
      "title": "Hessian Statistical Office – Historical Social Insurance Employment Statistics, 1974–2016",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/HEHeft_derivate_00007853/Z2_2j16.pdf",
      "justification": "Official historical statistical publication containing annual employment figures for workers subject to social insurance contributions in Hesse from 1974 to 2016. Includes the complete 1980–1989 period and employment breakdowns by economic sector. Particularly useful for analyzing structural changes in employment, industrial versus service-sector work, and labor market composition. These are employment indicators rather than direct measures of workplace conditions."
    },
    {
      "title": "Hessian Statistical Office – Historical Working Hours and Labor Volume in Hesse",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/HEHeft_derivate_00003097/Stawi-Juni-08.pdf",
      "justification": "Historical statistical analysis published in Staat und Wirtschaft in Hessen examining working hours and labor volume in the state. Discusses changes in hours worked per employed person, including developments during 1980–1991. Relevant for studying working-time reductions, part-time employment, and historical changes in labor utilization. Especially valuable because it directly addresses working hours in Hesse rather than relying exclusively on national statistics."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2023",
      "url_or_doi": "https://doi.org/10.4232/1.14695",
      "justification": "Long-running German social survey dataset incorporating observations from the 1980s through 2023. Contains information relevant to employment, occupational status, socioeconomic position, and social attitudes. Researchers can select observations from the 1980s to examine historical labor market experiences and compare them with later periods. Analysis specifically restricted to Hesse requires checking regional identifiers and access conditions."
    }
  ]
}
